import sys

def main():
    input_data = sys.stdin.read().split()
    idx = 0

    n = int(input_data[idx])
    idx += 1

    a = []
    for _ in range(n):
        a.append(int(input_data[idx]))
        idx += 1

    q = int(input_data[idx])
    idx += 1

    queries = []
    for _ in range(q):
        queries.append(int(input_data[idx]))
        idx += 1

    results = []

    for k in queries:
        count = 0
        for i in range(n):
            current_min = a[i]
            for j in range(i, n):
                if a[j] < current_min:
                    current_min = a[j]
                if current_min == k:
                    count += 1
        results.append(str(count))

    print('\n'.join(results))

if __name__ == "__main__":
    main()
